{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Under the new text, physical activity may include walking, jumping rope, playing volleyball, or other activity that promotes fitness and well-being.",
      "rationale": "Conveys the permitted activities and the fitness-and-well-being qualifier."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It may also include structured movement breaks.",
      "rationale": "Explicitly includes structured movement breaks as permissible physical activity."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It may include time in a physical education class, but only when students are physically active during that time.",
      "rationale": "Includes physical education class time with the required condition that students be physically active."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill also says that walking to and from class does not count as physical activity for this section.",
      "rationale": "Conveys the exclusion and limits it to the section being amended."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "A second change replaces a subdivision, (b)(2)(A)(ii), so that it says physical activity time does not include time when a student is permitted to use an electronic device.",
      "rationale": "Identifies the replaced subdivision and conveys the exclusion based on permission to use an electronic device."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "A third change replaces subdivision (b)(2)(B) with a rule that a teacher may keep a student from taking part in physical activity in order to improve the student's behavior.",
      "rationale": "Conveys the teacher's authority to prevent participation and the behavioral-improvement purpose."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill takes effect July 1, 2026, and would apply to the 2026-2027 school year and each school year after that.",
      "rationale": "States the exact effective date, initial applicable school year, and continuing applicability."
    }
  ]
}
